mapper.select:
SELECT template_id AS templateId, template_code AS templateCode, template_name AS templateName,
       version_no AS versionNo, scope_type AS scopeType, store_id AS storeId,
       body_template AS bodyTemplate, state, content_sha256 AS contentSha256,
       published_at AS publishedAt, version
FROM lbl_template
WHERE tenant_id = #{tenantId}
  AND (scope_type = 'TENANT'

      OR (scope_type = 'STORE' AND store_id IN
        #{storeId})

  )
  AND state = #{state}
ORDER BY template_code, version_no DESC, template_id DESC
LIMIT #{limit}
